// lib/pcb/stages/AddKeepoutsStage.ts
import { Pts as Pts5, Xy as Xy5, Zone as Zone2, ZoneKeepout, ZonePolygon as ZonePolygon2 } from "kicadts";
import { applyToPoint as applyToPoint12 } from "transformation-matrix";

// lib/pcb/stages/utils/circleToPolygon.ts
var CIRCLE_APPROX_SEGMENT_LENGTH = 0.2;
var CIRCLE_APPROX_MIN_STEPS = 16;
var CIRCLE_APPROX_MAX_STEPS = 128;
var circleToPolygon = (center, radius) => {
  const circumference = 2 * Math.PI * radius;
  let steps = Math.ceil(circumference / CIRCLE_APPROX_SEGMENT_LENGTH);
  steps = Math.max(
    CIRCLE_APPROX_MIN_STEPS,
    Math.min(CIRCLE_APPROX_MAX_STEPS, steps)
  );
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const angle = i / steps * Math.PI * 2;
    pts.push([
      center.x + radius * Math.cos(angle),
      center.y + radius * Math.sin(angle)
    ]);
  }
  return pts;
};

// lib/pcb/stages/AddKeepoutsStage.ts
var isPcbKeepout = (element) => element.type === "pcb_keepout";
