// lib/pcb/stages/utils/CreateFabricationNoteTextFromCircuitJson.ts
import {
  At as At3,
  GrText,
  TextEffects as TextEffects12,
  TextEffectsFont as TextEffectsFont12,
  TextEffectsJustify as TextEffectsJustify6
} from "kicadts";
import { applyToPoint as applyToPoint27 } from "transformation-matrix";
function createFabricationNoteTextFromCircuitJson({
  textElement,
  c2kMatPcb
}) {
  if (!textElement.text || !textElement.anchor_position) {
    return null;
  }
  const transformedPos = applyToPoint27(c2kMatPcb, {
    x: textElement.anchor_position.x,
    y: textElement.anchor_position.y
  });
  const layerMap = {
    top: "F.Fab",
    bottom: "B.Fab"
  };
  const kicadLayer = layerMap[textElement.layer] || textElement.layer || "F.Fab";
  const justify = new TextEffectsJustify6();
  const anchorAlignment = textElement.anchor_alignment || "center";
  switch (anchorAlignment) {
    case "top_left":
      justify.horizontal = "left";
      justify.vertical = "top";
      break;
    case "top_right":
      justify.horizontal = "right";
      justify.vertical = "top";
      break;
    case "bottom_left":
      justify.horizontal = "left";
      justify.vertical = "bottom";
      break;
    case "bottom_right":
      justify.horizontal = "right";
      justify.vertical = "bottom";
      break;
    case "center":
      break;
  }
  const font = new TextEffectsFont12();
  font.size = {
    width: textElement.font_size || 1,
    height: textElement.font_size || 1
  };
  font.thickness = 0.15;
  const textEffects = new TextEffects12({ font });
  if (anchorAlignment !== "center") {
    textEffects.justify = justify;
  }
  const position = new At3([transformedPos.x, transformedPos.y, 0]);
  const grText = new GrText({
    text: textElement.text,
    layer: kicadLayer,
    effects: textEffects,
    uuid: generateDeterministicUuid(
      textElement.pcb_fabrication_note_text_id ?? textElement.text
    )
  });
  grText.position = position;
  return grText;
}

// lib/pcb/stages/AddGraphicsStage.ts
import { applyToPoint as applyToPoint29, rotate as rotate12 } from "transformation-matrix";

// lib/pcb/stages/utils/CreateGrTextFromCircuitJson.ts
