  if (!ctx.includeBuiltins || ctx.builtinKicadSymbols.length === 0) return;
  const symbolLib = new KicadSymbolLib2({
    version: KICAD_SYM_LIB_VERSION2,
    generator: KICAD_GENERATOR,
    symbols: ctx.builtinKicadSymbols.map((s) => s.symbol)
  });
